import { findVerb } from './detectVerb.js';

// Subjects a drill card can be dealt with, and their row in the conjugation tables
const SUBJECTS = [
  ['yo', 0], ['tú', 1], ['él/ella', 2], ['usted', 2],
  ['nosotros', 3], ['ellos/ellas', 4], ['ustedes', 4],
];
// Drills without a subject to vary
const FIXED_TENSES = ['participio', 'gerundio', 'imperativo'];

/**
 * Deal a conjugation-drill card with a random subject, so the set can't be
 * memorized by position: "tener · yo → tuve" might come up as
 * "tener · ustedes → tuvieron". The answer is generated by the conjugator.
 * Cards that can't vary (participles, impersonal "hay", …) come back unchanged.
 * Dealt cards also get `display`, the prompt with the subject first.
 */
export function dealDrillCard(set, word) {
  if (!set.drill || FIXED_TENSES.includes(set.drill.tense)) return word;
  const parts = word.es.split('·').map((s) => s.trim());
  if (parts.length < 2 || parts[1] === '(hay)') return word;

  const verb = findVerb(word.es, true);
  const tense = set.drill.tense === 'fromPrompt' ? parts[2] : set.drill.tense;
  const forms = verb?.conjugation.tenses[tense];
  if (!forms) return word;

  const [label, row] = SUBJECTS[Math.floor(Math.random() * SUBJECTS.length)];
  return {
    ...word,
    es: [parts[0], label, ...parts.slice(2)].join(' · '), // canonical "verb · subject" form
    display: [label, parts[0], ...parts.slice(2)].join(' · '), // shown subject-first: "nosotros · tener"
    en: forms[row],
  };
}
